const CLIP = 1.2, T0 = .4;
const u = Math.min(1, (t - T0) / CLIP);            // 구간 안 위치 0 → 1
const x = lerp(120, 480, easeInOut(u));

const REPEAT = 3;
const r = t - T0;
const k = Math.min(REPEAT - 1, Math.floor(r / CLIP));   // 몇 회째(0부터)
const u = (r - k * CLIP) / CLIP;                        // 회 안의 위치
const x = lerp(120, 480, easeInOut(u));                 // 이음새에서 480 → 120 으로 튐

const reverse = k % 2 === 1;                            // 2회째, 4회째 …
const p = easeInOut(reverse ? 1 - u : u);
const x = lerp(120, 480, p);                            // 이음새에서 위치가 같음
